 "new",
 "new",
 "public isKindOfMethodMirror ^<Boolean> = (\n			^true\n		)",
 "public = other = (\n			other isKindOfMethodMirror ifFalse: [ ^false ].\n			^name = other name and: [ definingMixin = other definingMixin ]\n		)",
 "public hash ^<Integer> = (\n			^name hash bitXor: class hash\n		)",
 "public isSynthetic ^<Boolean> = (\n			(* MixinMirror>>methods already filters out isSynthetic methods, so any\n	   MethodMirror that exists in user-facing groups is non-synthetic.\n	   Returning false here matches what the IDE sees. A real fix would\n	   thread the flag through the constructor. *)\n			\n			^false\n		)",
 "public isPrimitive ^<Boolean> = (\n			(* JS-emitted methods have no [primitive] field; they're all plain JS\n	   functions. *)\n			\n			^false\n		)",
 "public primitive ^<Integer> = (\n			^0\n		)",
 "public selectors ^<List[Symbol]> = (\n			(* The selectors of every send in the method, decoded from its V5 bytecode record (psoup MethodMirror parity; drives senders). Methods without a record - JS-only bodies, images predating dual emission, reflectively edited classes - answer the empty list. *)\n\n			| record |\n			nil = simulation ifTrue: [ ^List new ].\n			record:: bytecodeRecord.\n			nil = record ifTrue: [ ^List new ].\n			^(simulation SelectorCollector overBytecode: (record at: 1)\n				literals: (record at: 2)) selectors\n		)",
 "bytecodeRecord = (\n			| mms |\n			mms:: _js propertyOf: (_js propertyOf: definingMixin reflectee\n					at: (_js literal: 'runtimeMixin'))\n				at: (_js literal: 'methods').\n			mms do: [:mm |\n					(_js propertyOf: mm at: (_js literal: 'name')) = name ifTrue: [\n\n							(* The MM constructor stores JS null for absent bytecode, which is NOT Newspeak nil: normalize here or the caller's nil test passes JS null through. *)\n							(_js operator: '==='\n								with: (_js propertyOf: mm at: (_js literal: 'bytecode'))\n								and: (_js ident: 'null')) ifTrue: [ ^nil ].\n							^_js propertyOf: mm at: (_js literal: 'bytecode')\n						]\n				].\n			^nil\n		)",
 "public simpleName ^<Symbol> = (\n			^name\n		)",
